import type {
  CoachingResponse,
  CrisisCategory,
  Language,
  SafetyResponse,
} from "./types";

/**
 * Predefined safety responses. They are written and reviewed by people, never generated by a
 * model, so the guidance is predictable. They do not contain phone numbers (these differ by
 * country), never say that anyone has been contacted, and do not ask investigative questions.
 *
 * Three kinds are kept distinct on purpose:
 *  - crisis: a safety concern was identified.
 *  - uncertain: the message could not be confidently judged safe. It does NOT claim a crisis.
 *  - screening_unavailable: the safety check failed. It does NOT claim anything about the message.
 */

interface Copy {
  message: string;
  actions: string[];
  follow_up: string;
}

