export function crisisReply(category: CrisisCategory, language: Language): SafetyResponse {
  return { type: "crisis", language, severity: "high", ...CRISIS[category][language] };
}

export function uncertainReply(language: Language): SafetyResponse {
  return { type: "uncertain", language, ...UNCERTAIN[language] };
}

export function unavailableReply(language: Language): SafetyResponse {
  return { type: "screening_unavailable", language, ...UNAVAILABLE[language] };
}

export function medicalReferralReply(language: Language): CoachingResponse {
  return { type: "coaching", language, ...MEDICAL_REFERRAL[language] };
}

const LANGUAGES: Language[] = ["en", "ur"];

/**
 * Recognises one of our own safety replies inside earlier conversation text. The server uses
 * this to restore a conversation's safety lock from the submitted history, rather than
 * trusting the client's safetyLocked flag.
 */
export function matchStoredSafetyReply(text: string): SafetyResponse | null {
  for (const language of LANGUAGES) {
    for (const category of Object.keys(CRISIS) as CrisisCategory[]) {
      if (text.includes(CRISIS[category][language].message)) return crisisReply(category, language);
    }
    if (text.includes(UNCERTAIN[language].message)) return uncertainReply(language);
    if (text.includes(UNAVAILABLE[language].message)) return unavailableReply(language);
  }
  return null;
}
